import{_ as c,C as h,o as s,c as u,a9 as r,b as i,w as t,a as n,E as a,a8 as d}from"./chunks/framework.BOiBTRPC.js";const v=JSON.parse('{"title":"The System Design Round","description":"The 45-minute data-platform design interview — the five-phase framework, three fully worked designs (real-time analytics, zero-downtime CDC migration, metrics/feature platform), and the junior-vs-senior rubric.","frontmatter":{"title":"The System Design Round","description":"The 45-minute data-platform design interview — the five-phase framework, three fully worked designs (real-time analytics, zero-downtime CDC migration, metrics/feature platform), and the junior-vs-senior rubric."},"headers":[],"relativePath":"interview/system-design.md","filePath":"interview/system-design.md"}'),m={name:"interview/system-design.md"};function p(g,e,f,b,y,w){const o=h("Mermaid"),l=h("QuizCard");return s(),u("div",null,[e[6]||(e[6]=r('<h1 id="the-system-design-round" tabindex="-1">The System Design Round <a class="header-anchor" href="#the-system-design-round" aria-label="Permalink to &quot;The System Design Round&quot;">​</a></h1><blockquote><p><strong>Why it matters</strong> — This is the round that decides senior vs staff. Nobody scores the boxes you draw; they score whether your requirements questions were sharp, whether your numbers were plausible, and whether you named the failure modes before being asked. Design rounds are a performance of judgment, not knowledge.</p></blockquote><h2 id="the-45-minute-framework" tabindex="-1">The 45-minute framework <a class="header-anchor" href="#the-45-minute-framework" aria-label="Permalink to &quot;The 45-minute framework&quot;">​</a></h2><p>The round has a rhythm. Candidates who manage the clock deliberately outperform those who let the interviewer drive:</p><table tabindex="0"><thead><tr><th>Phase</th><th>Time</th><th>What you produce</th><th>The signal</th></tr></thead><tbody><tr><td>1. Requirements</td><td>0-8 min</td><td>Functional + non-functional requirements, agreed grain, scale inputs</td><td>Senior = asks before drawing</td></tr><tr><td>2. Estimation</td><td>8-13 min</td><td>Back-of-envelope: events/s, storage/day, partition counts, cost sketch</td><td>Numbers over adjectives</td></tr><tr><td>3. High-level design</td><td>13-25 min</td><td>5-8 boxes: ingest → buffer → process → store → serve, observability as a peer</td><td>Clean layered diagram</td></tr><tr><td>4. Deep dives</td><td>25-38 min</td><td>2-3 components drilled: consistency, semantics, failure handling</td><td>Trade-offs volunteered, not extracted</td></tr><tr><td>5. Bottlenecks + wrap</td><td>38-45 min</td><td>What breaks first, scaling plan, what you&#39;d monitor</td><td>Failure-mode ownership</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight</p><p>Say your time budget out loud at minute zero: &quot;I&#39;ll spend ~8 minutes on requirements, then estimation, a high-level sketch, and I&#39;d like to deep-dive on exactly-once handling and backfills — sound right?&quot; You&#39;ve just converted a passive session into a managed one — and guaranteed the interviewer knows your plan when time runs short.</p></div><p>Alex Xu&#39;s 4-step process is the skeleton under that clock. Mapped to a data-platform prompt:</p><table tabindex="0"><thead><tr><th>Xu step</th><th>What you do</th><th>The data-platform version</th><th>Interviewer reads</th></tr></thead><tbody><tr><td>1. Understand &amp; scope</td><td>Clarify requirements and assumptions before solving</td><td>Freshness SLO, correctness tolerance, consumers, grain, replay needs</td><td>Whether the system you design is the one they asked for</td></tr><tr><td>2. High-level + buy-in</td><td>Sketch the blueprint, get agreement, sanity-check with estimation</td><td>Ingest → buffer → process → store → serve boxes; run the numbers to justify each box</td><td>Whether you can defend a design instead of just drawing it</td></tr><tr><td>3. Deep dive</td><td>Drill the components that carry the design</td><td>The 2-3 hard parts: dedupe window, exactly-once boundary, restatement handling</td><td>Depth on demand — do you know <em>why</em>, not just <em>what</em></td></tr><tr><td>4. Wrap up</td><td>Bottlenecks, error cases, monitoring, next scale</td><td>First failure at 10×, mitigation, observability story, trade-off recap</td><td>Whether you close the loop like an owner</td></tr></tbody></table><p>Two rules carry over verbatim: don&#39;t jump to an answer (Xu&#39;s cautionary tale is the kid who answers every question instantly — speed reads as guessing, not seniority), and treat the interviewer as a teammate you check in with, not a judge you perform at.</p><h2 id="the-requirements-questions-that-separate-levels" tabindex="-1">The requirements questions that separate levels <a class="header-anchor" href="#the-requirements-questions-that-separate-levels" aria-label="Permalink to &quot;The requirements questions that separate levels&quot;">​</a></h2><p>For <em>any</em> data-platform prompt, these five questions unlock the design:</p><ol><li><strong>&quot;What decisions does this data drive?&quot;</strong> — determines freshness SLO. Dashboards for execs ≠ fraud blocking ≠ ML features.</li><li><strong>&quot;What&#39;s the arrival pattern — volume, peaks, late/out-of-order?&quot;</strong> — determines buffer, windows, watermarks.</li><li><strong>&quot;How wrong can it be, for how long?&quot;</strong> — determines correctness/completeness requirements: dupes tolerable? Restatement acceptable?</li><li><strong>&quot;Who consumes it, in what shape?&quot;</strong> — determines serving layer: SQL marts, APIs, feature lookups.</li><li><strong>&quot;What&#39;s the replay/backfill story?&quot;</strong> — determines whether raw must be immutable and how long you retain it.</li></ol><h2 id="the-estimation-cheat-sheet" tabindex="-1">The estimation cheat-sheet <a class="header-anchor" href="#the-estimation-cheat-sheet" aria-label="Permalink to &quot;The estimation cheat-sheet&quot;">​</a></h2><p>Xu&#39;s chapter 2 condenses Jeff Dean&#39;s latency numbers and powers of two into the math a design round actually uses. The DE version of the same sheet:</p><h3 id="powers-of-two" tabindex="-1">Powers of two <a class="header-anchor" href="#powers-of-two" aria-label="Permalink to &quot;Powers of two&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Unit</th><th>Bytes</th><th>Say it as</th></tr></thead><tbody><tr><td>1 KB</td><td>2^10 ≈ 1 thousand</td><td>thousand</td></tr><tr><td>1 MB</td><td>2^20 ≈ 1 million</td><td>million</td></tr><tr><td>1 GB</td><td>2^30 ≈ 1 billion</td><td>billion</td></tr><tr><td>1 TB</td><td>2^40 ≈ 1 trillion</td><td>trillion</td></tr><tr><td>1 PB</td><td>2^50 ≈ 1 quadrillion</td><td>quadrillion</td></tr></tbody></table><p>The interview shortcut: 2^10 ≈ 10^3. Every conversion reduces to counting thousands — 86,400 seconds/day becomes ~10^5 s/day, which is the single most useful constant in data-platform estimation.</p><h3 id="latency-numbers-worth-memorizing" tabindex="-1">Latency numbers worth memorizing <a class="header-anchor" href="#latency-numbers-worth-memorizing" aria-label="Permalink to &quot;Latency numbers worth memorizing&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Operation</th><th>Order of magnitude</th><th>Why a DE cares</th></tr></thead><tbody><tr><td>L1/L2 cache reference</td><td>~1-10 ns</td><td>Why hot aggregates live in-process</td></tr><tr><td>Main memory reference</td><td>~100 ns</td><td>In-memory dedupe sets are free relative to disk</td></tr><tr><td>Send 2KB over 1 Gbps network</td><td>~20 µs</td><td>Batch records before shipping — per-record network cost dominates</td></tr><tr><td>Read 1 MB sequentially from SSD</td><td>~1 ms</td><td>Sequential scans are cheap; random reads are not</td></tr><tr><td>Disk seek</td><td>~10 ms</td><td>Why event logs append and never update in place</td></tr><tr><td>Read 1 MB sequentially from disk</td><td>~30 ms</td><td>Partition pruning turns a 30 ms/unit scan into a plan, not a scan of everything</td></tr><tr><td>Send packet CA → Netherlands → CA</td><td>~150 ms</td><td>Cross-region replication latency bounds any global-consistency promise</td></tr></tbody></table><p>Three conclusions carry straight into DE rounds: memory is fast and disk is slow, so buffer and batch; compress before sending over the network; cross-region traffic is measured in hundreds of milliseconds — never promise a globally consistent real-time dashboard.</p><h3 id="the-five-estimation-moves-interviewers-grade" tabindex="-1">The five estimation moves interviewers grade <a class="header-anchor" href="#the-five-estimation-moves-interviewers-grade" aria-label="Permalink to &quot;The five estimation moves interviewers grade&quot;">​</a></h3><ol><li><strong>QPS / events-per-second</strong> — DAU × actions ÷ ~10^5 s. Then <strong>peak QPS ≈ 2× average</strong> (Xu&#39;s rule of thumb; for batch data sources it&#39;s the end-of-window burst, not daily average, that sizes your buffer).</li><li><strong>Storage per day</strong> — events/s × bytes/event × 86,400 (~10^5 s). 10k ev/s × 1 KB ≈ 1 TB/day — two multiplications, done.</li><li><strong>Retention → total storage</strong> — per-day × days; state replication factor (~3×) only if asked, but know it&#39;s there.</li><li><strong>Throughput</strong> — storage/day ÷ 10^5 s gives sustained MB/s; compare against disk (~30 ms per sequential MB) and network (~20 µs per small packet) to prove your design fits in one sentence.</li><li><strong>Count of machines/partitions</strong> — total throughput ÷ per-node throughput. Rounding aggressively is expected — precision is not the graded signal.</li></ol><details class="details custom-block"><summary>The process is the answer</summary><p>Xu&#39;s estimation tips: round hard (99987/9.1 becomes 100,000/10), write assumptions where the interviewer can see them, label every number with units, and narrate constantly. Interviewers grade the path — &quot;150M DAU × 2 events = 300M/day ≈ 3.5k/s, call peak 7k/s&quot; — not the arithmetic. A wrong number with a sound process scores better than a right number you reached silently.</p></details><h2 id="design-a-—-real-time-analytics-pipeline" tabindex="-1">Design A — Real-time analytics pipeline <a class="header-anchor" href="#design-a-—-real-time-analytics-pipeline" aria-label="Permalink to &quot;Design A — Real-time analytics pipeline&quot;">​</a></h2><p><em>&quot;Design a pipeline that ingests clickstream events (10k/s peak), powers near-real-time dashboards, and lands in a lakehouse for analysts.&quot;</em></p><h3 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Question</th><th>Assumed answer (state it, invite correction)</th></tr></thead><tbody><tr><td>Freshness</td><td>Dashboards lag ≤1 min; lakehouse ≤15 min</td></tr><tr><td>Correctness</td><td>Metrics must not double-count on retries; small gaps acceptable during incidents</td></tr><tr><td>Consumers</td><td>Live dashboards (low-latency aggregates) + analysts (SQL on lake)</td></tr><tr><td>Lateness</td><td>Mobile events can arrive hours late; must be absorbed, not dropped</td></tr><tr><td>Shape</td><td>Append-only events, keyed by event_id, partitioned by event_time</td></tr></tbody></table><h3 id="capacity-math" tabindex="-1">Capacity math <a class="header-anchor" href="#capacity-math" aria-label="Permalink to &quot;Capacity math&quot;">​</a></h3><ul><li><strong>Throughput:</strong> 10k events/s × ~600 B ≈ <strong>6 MB/s</strong> — trivial for Kafka (3-6 partitions is plenty; add headroom → 12).</li><li><strong>Storage:</strong> 6 MB/s × 86,400 s ≈ <strong>500 GB/day</strong>; ×3 replication × 7-day retention ≈ <strong>~10 TB hot</strong> in the log; lake gets ~180 TB/yr raw, ~50 TB post-columnar compression.</li><li><strong>The number that matters:</strong> not ingest rate — it&#39;s <em>dedupe window</em> size and <em>recompute</em> cost of restating a week of aggregates.</li></ul>',29)),(s(),i(d,null,{default:t(()=>[a(o,{id:"mermaid-526",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20Producers%5B%22Event%20producers%22%5D%0A%20%20%20%20%20%20%20%20W%5B%22Web%20SDK%22%5D%20--%3E%20K%0A%20%20%20%20%20%20%20%20M%5B%22Mobile%20SDK%3Cbr%2F%3Ebatches%2C%20can%20be%20hours%20late%22%5D%20--%3E%20K%0A%20%20%20%20end%0A%20%20%20%20K%5B%22Kafka%20%E2%80%94%20durable%20log%2C%3Cbr%2F%3E12%20partitions%2C%20keyed%20by%20event_id%22%5D%0A%20%20%20%20subgraph%20Processing%5B%22Stream%20processing%20%E2%80%94%20Flink%22%5D%0A%20%20%20%20%20%20%20%20F1%5B%22Event-time%20windows%3Cbr%2F%3Ewatermark%20~2%20min%20lateness%22%5D%0A%20%20%20%20%20%20%20%20F2%5B%22Dedupe%20state%3Cbr%2F%3Ekeyed%20on%20event_id%22%5D%0A%20%20%20%20%20%20%20%20F3%5B%221-min%20aggregates%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Sinks%5B%22Sinks%22%5D%0A%20%20%20%20%20%20%20%20O%5B%22OLAP%20store%20%E2%80%94%20sub-second%3Cbr%2F%3Edashboard%20queries%22%5D%0A%20%20%20%20%20%20%20%20L%5B%22Lakehouse%20%E2%80%94%20Iceberg%2C%3Cbr%2F%3E15-min%20micro-batches%22%5D%0A%20%20%20%20%20%20%20%20D%5B%22DLQ%20%2B%20replay%20path%22%5D%0A%20%20%20%20end%0A%20%20%20%20K%20--%3E%20F1%20--%3E%20F2%20--%3E%20F3%0A%20%20%20%20F3%20--%3E%7C%22exactly-once-ish%3A%20transactional%20write%3Cbr%2F%3Eor%20upsert%20by%20window%20key%22%7C%20O%0A%20%20%20%20F3%20--%3E%7C%22idempotent%20file%20commit%22%7C%20L%0A%20%20%20%20F1%20-.-%3E%7C%22poison%20%2F%20unparseable%22%7C%20D%0A%20%20%20%20L%20--%3E%20B%5B%22BI%20%2F%20analysts%3Cbr%2F%3ESQL%20on%20curated%20marts%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=r('<h3 id="decision-points-—-narrate-the-trade-off" tabindex="-1">Decision points — narrate the trade-off <a class="header-anchor" href="#decision-points-—-narrate-the-trade-off" aria-label="Permalink to &quot;Decision points — narrate the trade-off&quot;">​</a></h3><ul><li><strong>&quot;Exactly-once&quot;:</strong> say <em>effective-once</em>. Flink checkpointing + transactional sink covers inside-the-framework; the OLAP upsert keyed on (window, dimension) makes retries harmless anyway. At-least-once + idempotent sink beats an exotic exactly-once setup — cheaper, simpler, same observable guarantee.</li><li><strong>Late data:</strong> watermark at ~2 min for the dashboard path (dashboards tolerate eventual correction); lake path keeps a longer lookback — late events update Iceberg partitions via upsert, and dashboards restate on next read.</li><li><strong>Two sinks, one source of truth:</strong> the lake is canonical; the OLAP store is a disposable projection. If they disagree, rebuild OLAP from lake — naming the recovery story is the senior move.</li></ul><h3 id="failure-modes-to-volunteer" tabindex="-1">Failure modes to volunteer <a class="header-anchor" href="#failure-modes-to-volunteer" aria-label="Permalink to &quot;Failure modes to volunteer&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Failure</th><th>Handling</th></tr></thead><tbody><tr><td>Mobile events arrive 6h late</td><td>Long-lookback lake upsert; dashboard accepts restatement or uses allowed-lateness windows</td></tr><tr><td>Flink job down 3h</td><td>Kafka retention covers it; on restart, catch-up processing — lag metric alerts at 15 min</td></tr><tr><td>Duplicate delivery on retry</td><td>Dedupe keyed on event_id within window + idempotent upsert at sink</td></tr><tr><td>Poison record</td><td>Bounded retries → DLQ with payload + offset; replay path after fix</td></tr><tr><td>Traffic spike 10×</td><td>Kafka absorbs; autoscalers on consumer lag; dashboards degrade gracefully, lake lags but doesn&#39;t lose</td></tr></tbody></table><h3 id="follow-ups-interviewers-ask" tabindex="-1">Follow-ups interviewers ask <a class="header-anchor" href="#follow-ups-interviewers-ask" aria-label="Permalink to &quot;Follow-ups interviewers ask&quot;">​</a></h3><ul><li><em>&quot;What if event_id isn&#39;t trustworthy?&quot;</em> → content-hash fallback + producer-side dedupe; state the residual dup risk.</li><li><em>&quot;Dashboard shows a dip — bug or real?&quot;</em> → completeness SLI: expected vs actual volume per window; that&#39;s the monitoring answer.</li><li><em>&quot;Make it exactly-once end-to-end.&quot;</em> → explain Two Generals; offer effective-once via outbox/transactional sink and name the cost.</li></ul><h2 id="design-b-—-zero-downtime-cdc-migration-of-a-2tb-oltp-db" tabindex="-1">Design B — Zero-downtime CDC migration of a 2TB OLTP DB <a class="header-anchor" href="#design-b-—-zero-downtime-cdc-migration-of-a-2tb-oltp-db" aria-label="Permalink to &quot;Design B — Zero-downtime CDC migration of a 2TB OLTP DB&quot;">​</a></h2><p><em>&quot;Migrate a 2TB Postgres OLTP database to the data lake — no downtime, no lost writes, verifiable correctness.&quot;</em></p><h3 id="requirements-1" tabindex="-1">Requirements <a class="header-anchor" href="#requirements-1" aria-label="Permalink to &quot;Requirements&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Question</th><th>Answer</th></tr></thead><tbody><tr><td>Downtime budget</td><td>Zero — OLTP stays live throughout</td></tr><tr><td>Consistency</td><td>Cutover point must be provable; no lost or duplicated writes</td></tr><tr><td>Validation</td><td>Row counts + checksums per table before and after cutover</td></tr><tr><td>Rollback</td><td>Must be able to revert for a stabilization window</td></tr><tr><td>Ongoing</td><td>Post-migration, the lake becomes the read replica for analytics</td></tr></tbody></table><h3 id="the-plan-—-snapshot-cdc-tail-dual-run-cutover" tabindex="-1">The plan — snapshot + CDC tail, dual-run, cutover <a class="header-anchor" href="#the-plan-—-snapshot-cdc-tail-dual-run-cutover" aria-label="Permalink to &quot;The plan — snapshot + CDC tail, dual-run, cutover&quot;">​</a></h3>',11)),(s(),i(d,null,{default:t(()=>[a(o,{id:"mermaid-690",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20Phase1%5B%22Phase%201%20%E2%80%94%20parallel%20run%22%5D%0A%20%20%20%20%20%20%20%20DB%5B%22Postgres%20OLTP%3Cbr%2F%3Estays%20live%2C%20source%20of%20truth%22%5D%0A%20%20%20%20%20%20%20%20DB%20--%3E%7C%22consistent%20snapshot%3Cbr%2F%3Epg_dump%20or%20storage%20snapshot%22%7C%20SNAP%5B%22Bulk%20load%3Cbr%2F%3E2TB%20into%20lake%20raw%22%5D%0A%20%20%20%20%20%20%20%20DB%20--%3E%7C%22WAL%20%2F%20logical%20replication%22%7C%20CDC%5B%22Debezium%20CDC%3Cbr%2F%3Estreams%20changes%22%5D%0A%20%20%20%20%20%20%20%20SNAP%20--%3E%20L%5B%22Lake%20%E2%80%94%20Iceberg%20tables%3Cbr%2F%3Esnapshot%20%2B%20incremental%20apply%22%5D%0A%20%20%20%20%20%20%20%20CDC%20--%3E%20L%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Phase2%5B%22Phase%202%20%E2%80%94%20validate%22%5D%0A%20%20%20%20%20%20%20%20L%20--%3E%20V%5B%22Reconciliation%20%E2%80%94%20per-table%3Cbr%2F%3Erow%20counts%20%2B%20checksums%20%2B%20lag%20metrics%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Phase3%5B%22Phase%203%20%E2%80%94%20cutover%22%5D%0A%20%20%20%20%20%20%20%20V%20--%3E%7C%22lag%20%E2%89%88%200%2C%20checksums%20match%22%7C%20SW%5B%22Point%20reads%20at%20lake%3Cbr%2F%3Eor%20keep%20CDC%20as%20live%20replica%22%5D%0A%20%20%20%20%20%20%20%20DB%20-.-%3E%7C%22rollback%3A%20still%20live%2C%3Cbr%2F%3Enothing%20was%20deleted%22%7C%20SW%0A%20%20%20%20end%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[n(" Loading... ",-1)])]),_:1})),e[8]||(e[8]=r('<h3 id="capacity-math-1" tabindex="-1">Capacity math <a class="header-anchor" href="#capacity-math-1" aria-label="Permalink to &quot;Capacity math&quot;">​</a></h3><ul><li>Snapshot copy: 2TB over a 1 Gbps pipe ≈ <strong>~4.5 hours</strong> — do it off-peak or throttle; storage snapshot + restore is faster but couples you to the engine.</li><li>CDC lag: typical WAL rate on a busy OLTP ~50-200 MB/hr — catch-up after snapshot lands is minutes, not hours. Measure it; don&#39;t guess.</li><li>Validation: checksumming 2TB is a scan, not a migration — run it per-table per-partition, in parallel, and <em>before</em> cutover while CDC keeps both sides current.</li></ul><h3 id="decision-points" tabindex="-1">Decision points <a class="header-anchor" href="#decision-points" aria-label="Permalink to &quot;Decision points&quot;">​</a></h3><ul><li><p><strong>Snapshot consistency:</strong> the snapshot must be <em>at a known WAL position</em>. The textbook approach — Debezium&#39;s incremental snapshot or a consistent point-in-time snapshot + log position — lets CDC apply changes <em>from that exact LSN</em> so nothing is skipped or double-applied. Say &quot;LSN-consistent&quot; and the interviewer knows you&#39;ve done this.</p></li><li><p><strong>Cutover semantics:</strong> readers cut to the lake (or lake-fed replica) only after reconciliation shows zero-lag parity; writes never move — the OLTP remains source of truth. &quot;Migrate reads, not writes&quot; is the safest interpretation; if writes must move, you need dual-write fencing and a rollback bridge — name that cost.</p></li><li><p><strong>Deletes:</strong> CDC must propagate deletes (tombstones → Iceberg delete files or soft-delete flags), not just upserts. Forgetting deletes is the classic silent divergence.</p></li><li><p><strong>Schema drift during migration:</strong> source DDL during the window breaks naive replication — the schema registry / CDC connector handles compatible changes; breaking changes need a coordinated pause.</p></li></ul><details class="details custom-block"><summary>The interview cheat: what &quot;2TB&quot; actually implies</summary><p>2TB is small enough that the honest answer includes &quot;a plain <code>pg_dump</code> + restore would work for most teams — if we could take downtime.&quot; Saying that <em>first</em>, then explaining why the requirement rules it out, shows you know the boring answer and chose the complex one for a reason. Interviewers specifically probe for candidates who reach for CDC when a weekend-migration window would have been simpler and cheaper.</p></details><h3 id="failure-modes" tabindex="-1">Failure modes <a class="header-anchor" href="#failure-modes" aria-label="Permalink to &quot;Failure modes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Failure</th><th>Handling</th></tr></thead><tbody><tr><td>Snapshot stale before CDC caught up</td><td>LSN-anchored CDC resumes from snapshot point — no gap</td></tr><tr><td>CDC connector dies mid-tail</td><td>Checkpointed WAL position → resume; lag metric pages at threshold</td></tr><tr><td>Checksum mismatch on a table</td><td>Re-reconcile that table only; mismatches usually = in-flight txns or deletes not propagated</td></tr><tr><td>Need rollback post-cutover</td><td>OLTP untouched → repoint reads; the lake was never the writer</td></tr><tr><td>PK-free tables</td><td>CDC needs a replica identity; pre-migration audit finds and fixes these — <em>volunteer this check</em></td></tr></tbody></table><h3 id="follow-ups" tabindex="-1">Follow-ups <a class="header-anchor" href="#follow-ups" aria-label="Permalink to &quot;Follow-ups&quot;">​</a></h3><ul><li><em>&quot;How do you prove correctness?&quot;</em> → three layers: row counts per table, sampled row-level checksums, and application-level invariants (order totals reconcile). Counts alone miss corruption.</li><li><em>&quot;What if the source is still being written during snapshot?&quot;</em> → that&#39;s exactly why snapshot alone is insufficient; WAL tail covers it — this is <em>the</em> question the design exists to answer.</li></ul><h2 id="design-c-—-metrics-feature-platform-serving-bi-and-ml" tabindex="-1">Design C — Metrics / feature platform serving BI and ML <a class="header-anchor" href="#design-c-—-metrics-feature-platform-serving-bi-and-ml" aria-label="Permalink to &quot;Design C — Metrics / feature platform serving BI and ML&quot;">​</a></h2><p><em>&quot;Design a platform that computes business metrics and ML features from shared pipelines — BI wants freshness SLAs, ML wants point-in-time correctness.&quot;</em></p><h3 id="requirements-2" tabindex="-1">Requirements <a class="header-anchor" href="#requirements-2" aria-label="Permalink to &quot;Requirements&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Question</th><th>Answer</th></tr></thead><tbody><tr><td>Consumers</td><td>BI dashboards (SQL marts, 15-min freshness) + ML features (online lookup &lt;10ms, offline training sets)</td></tr><tr><td>The hard constraint</td><td>Same data feeds both — metric drift and training-serving skew are the named risks</td></tr><tr><td>Scale</td><td>200 metric/feature definitions, ~50 upstream tables, retrains daily</td></tr><tr><td>Correctness</td><td>Offline features must be point-in-time correct (no leakage); BI metrics must be reproducible</td></tr></tbody></table>',13)),(s(),i(d,null,{default:t(()=>[a(o,{id:"mermaid-868",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20Shared%5B%22Shared%20upstream%20%E2%80%94%20one%20source%20of%20truth%22%5D%0A%20%20%20%20%20%20%20%20RAW%5B%22Raw%20immutable%20events%3Cbr%2F%3Eand%20CDC%20tables%22%5D%20--%3E%20CUR%5B%22Curated%20conform%20layer%3Cbr%2F%3Ededuped%2C%20modeled%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Def%5B%22Definition%20layer%20%E2%80%94%20single%20spec%22%5D%0A%20%20%20%20%20%20%20%20DEF%5B%22Metric%20%2F%20feature%20definitions%3Cbr%2F%3Ein%20code%20%E2%80%94%20one%20place%2C%20versioned%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20BI%5B%22BI%20path%20%E2%80%94%20freshness%20SLO%22%5D%0A%20%20%20%20%20%20%20%20MARTS%5B%22Marts%20%2B%20aggregates%3Cbr%2F%3E15-min%20incremental%20builds%22%5D%20--%3E%20SEM%5B%22Semantic%20layer%3Cbr%2F%3Emetrics%20served%20to%20BI%20tools%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20ML%5B%22ML%20path%20%E2%80%94%20correctness%20SLO%22%5D%0A%20%20%20%20%20%20%20%20OFF%5B%22Offline%20feature%20store%3Cbr%2F%3Epoint-in-time%20joins%20for%20training%22%5D%0A%20%20%20%20%20%20%20%20ON%5B%22Online%20store%20%E2%80%94%20low-latency%3Cbr%2F%3Efeature%20lookup%20for%20serving%22%5D%0A%20%20%20%20%20%20%20%20OFF%20--%3E%20ON%0A%20%20%20%20end%0A%20%20%20%20CUR%20--%3E%20MARTS%0A%20%20%20%20CUR%20--%3E%20OFF%0A%20%20%20%20DEF%20-.-%3E%7C%22compiles%20to%20both%20paths%22%7C%20MARTS%0A%20%20%20%20DEF%20-.-%3E%7C%22same%20definitions%22%7C%20OFF%0A%20%20%20%20ON%20--%3E%20SVC%5B%22Model%20serving%22%5D%0A%20%20%20%20SEM%20--%3E%20DASH%5B%22Dashboards%22%5D%0A"})]),fallback:t(()=>[...e[2]||(e[2]=[n(" Loading... ",-1)])]),_:1})),e[9]||(e[9]=r('<h3 id="capacity-math-2" tabindex="-1">Capacity math <a class="header-anchor" href="#capacity-math-2" aria-label="Permalink to &quot;Capacity math&quot;">​</a></h3><ul><li>Online serving: 1k lookups/s × ~1KB feature vectors — any KV store handles this; the SLO is &lt;10ms p99, so the store choice matters less than <em>feature precomputation</em>: never compute at lookup time.</li><li>Offline: daily point-in-time joins over 6 months of events ≈ a scheduled Spark job; the cost driver is <strong>backfills</strong> when a definition changes — 200 definitions × recompute is why definitions live in code with version pinning.</li></ul><h3 id="decision-points-1" tabindex="-1">Decision points <a class="header-anchor" href="#decision-points-1" aria-label="Permalink to &quot;Decision points&quot;">​</a></h3><ul><li><strong>One definition, two engines:</strong> a metric defined twice (once in dbt, once in the feature store) <em>will</em> drift. The platform answer: definitions-as-code compiled to both paths, or accept drift with reconciliation checks. This is the design&#39;s central tension — spend your deep-dive here.</li><li><strong>Point-in-time correctness:</strong> offline features must join labels as-of event time (ASOF joins), not current values — otherwise you ship leakage. Name &quot;training-serving skew&quot; and &quot;leakage&quot; explicitly; they&#39;re the vocabulary check.</li><li><strong>Freshness vs correctness:</strong> BI wants the newest data; ML wants reproducible data. Resolution: the lake is immutable and versioned — BI reads latest, training reads a frozen snapshot. Both from the same raw.</li><li><strong>SLA ownership:</strong> when a metric is wrong, who owns it? The platform answer: definition owner + platform SLOs on the pipeline (freshness/completeness SLIs), not per-dashboard monitoring.</li></ul><h3 id="failure-modes-1" tabindex="-1">Failure modes <a class="header-anchor" href="#failure-modes-1" aria-label="Permalink to &quot;Failure modes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Failure</th><th>Handling</th></tr></thead><tbody><tr><td>Metric drifts between BI and feature paths</td><td>Single definition layer; reconciliation job comparing outputs</td></tr><tr><td>Training-serving skew</td><td>Same computation code for offline/online; skew tests in CI</td></tr><tr><td>Upstream late data restates metrics</td><td>Versioned/snapshot reads for ML; BI accepts restatement with a stated window</td></tr><tr><td>Feature definition change breaks backfill compat</td><td>Definitions versioned; training sets pin the version used</td></tr><tr><td>Online store stale after pipeline outage</td><td>Freshness SLI per feature group + fallback to last-good snapshot</td></tr></tbody></table><h3 id="follow-ups-1" tabindex="-1">Follow-ups <a class="header-anchor" href="#follow-ups-1" aria-label="Permalink to &quot;Follow-ups&quot;">​</a></h3><ul><li><em>&quot;Analysts want a new metric tomorrow — what&#39;s the path?&quot;</em> → definition PR → compiled to marts → backfill → published to semantic layer. Speed of <em>adding</em> metrics is the platform&#39;s real product.</li><li><em>&quot;Where does streaming fit?&quot;</em> → only where the SLO demands it: fraud features near-real-time; daily aggregates batch. Resist stream-everything.</li></ul><h2 id="design-d-—-distributed-message-queue" tabindex="-1">Design D — Distributed message queue <a class="header-anchor" href="#design-d-—-distributed-message-queue" aria-label="Permalink to &quot;Design D — Distributed message queue&quot;">​</a></h2><p><em>&quot;Design a Kafka — a durable, replayable, partitioned event log with consumer groups and configurable delivery semantics.&quot;</em> (Vol 2 ch.4 — this is the chapter where DE candidates win or lose the round.)</p><h3 id="requirements-3" tabindex="-1">Requirements <a class="header-anchor" href="#requirements-3" aria-label="Permalink to &quot;Requirements&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Question</th><th>Assumed answer (state it, invite correction)</th></tr></thead><tbody><tr><td>Core functions</td><td>Producers append; consumers read; consumers can replay history, not just drain</td></tr><tr><td>Delivery semantics</td><td>Configurable per client: at-most-once, at-least-once, exactly-once (the hard one)</td></tr><tr><td>Ordering</td><td>Ordered within a partition only — never promise global order</td></tr><tr><td>Retention</td><td>Days on disk, replayable; unlike RabbitMQ, the queue doesn&#39;t delete on consume</td></tr><tr><td>Message size</td><td>KB range; no multi-MB blobs — say so or someone designs for video</td></tr><tr><td>Latency vs throughput</td><td>Tunable per topic: batch-tuned for log pipelines, low-latency for transactional events</td></tr></tbody></table><h3 id="capacity-math-3" tabindex="-1">Capacity math <a class="header-anchor" href="#capacity-math-3" aria-label="Permalink to &quot;Capacity math&quot;">​</a></h3><ul><li><strong>Throughput:</strong> 10k msgs/s avg × ~1 KB ≈ <strong>10 MB/s</strong> ingest — one partition handles it; you partition for <em>parallel consumers</em>, not for raw write throughput.</li><li><strong>Storage:</strong> 10 MB/s ≈ <strong>~1 TB/day</strong>; ×3 replicas × 7-day retention ≈ <strong>~21 TB</strong> hot on brokers — cheap spinning disks, sequential I/O, that&#39;s the whole storage argument.</li><li><strong>The number that matters:</strong> partition count × consumer parallelism — rebalancing a group over hundreds of consumers takes <em>minutes</em>. Size partitions for the growth estimate up front (30%/yr → 2× in ~3 years); re-keying partitions in production is a migration, not a config change.</li></ul>',14)),(s(),i(d,null,{default:t(()=>[a(o,{id:"mermaid-1072",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20Producers%0A%20%20%20%20%20%20%20%20P1%5B%22Producer%20client%3Cbr%2F%3Erouting%20%2B%20batch%20buffer%22%5D%0A%20%20%20%20%20%20%20%20P2%5B%22Producer%20client%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Brokers%5B%22Broker%20cluster%22%5D%0A%20%20%20%20%20%20%20%20B1%5B%22Broker%201%3Cbr%2F%3EP0%20leader%2C%20P2%20follower%22%5D%0A%20%20%20%20%20%20%20%20B2%5B%22Broker%202%3Cbr%2F%3EP1%20leader%2C%20P0%20follower%22%5D%0A%20%20%20%20%20%20%20%20B3%5B%22Broker%203%3Cbr%2F%3EP2%20leader%2C%20P1%20follower%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Coord%5B%22Coordination%20service%22%5D%0A%20%20%20%20%20%20%20%20ZK%5B%22Metadata%20%2B%20replica%20plan%3Cbr%2F%3Eleader%20election%22%5D%0A%20%20%20%20%20%20%20%20SS%5B%22Consumer%20group%20state%3Cbr%2F%3Ecommitted%20offsets%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Consumers%5B%22Consumer%20group%22%5D%0A%20%20%20%20%20%20%20%20C1%5B%22Consumer%20A%3Cbr%2F%3Ereads%20P0%22%5D%0A%20%20%20%20%20%20%20%20C2%5B%22Consumer%20B%3Cbr%2F%3Ereads%20P1%2C%20P2%22%5D%0A%20%20%20%20end%0A%20%20%20%20P1%20--%3E%7Cappend%2C%20leader%20only%7C%20B1%0A%20%20%20%20P2%20--%3E%7Cappend%2C%20leader%20only%7C%20B2%0A%20%20%20%20B1%20-.-%3E%7Cfollower%20pulls%7C%20B2%0A%20%20%20%20B3%20-.-%3E%7Cfollower%20pulls%7C%20B1%0A%20%20%20%20ZK%20-.-%3E%20Brokers%0A%20%20%20%20SS%20-.-%3E%20Consumers%0A%20%20%20%20B1%20--%3E%7Cpoll%20fetch%7C%20C1%0A%20%20%20%20B2%20--%3E%7Cpoll%20fetch%7C%20C2%0A%20%20%20%20B3%20--%3E%7Cpoll%20fetch%7C%20C2%0A"})]),fallback:t(()=>[...e[3]||(e[3]=[n(" Loading... ",-1)])]),_:1})),e[10]||(e[10]=r('<h3 id="decision-points-—-narrate-the-trade-off-1" tabindex="-1">Decision points — narrate the trade-off <a class="header-anchor" href="#decision-points-—-narrate-the-trade-off-1" aria-label="Permalink to &quot;Decision points — narrate the trade-off&quot;">​</a></h3><ul><li><strong>Storage is a WAL, not a database:</strong> write-heavy, read-heavy, <em>sequential-only</em>, no updates. A relational or NoSQL store pays B-tree/random-access costs for a workload that is pure append. WAL segmented per partition, new messages to the active segment, old segments serve reads until retention truncates them. Sequential I/O + OS page cache gets hundreds of MB/s per disk — the &quot;disks are slow&quot; intuition only applies to random access.</li><li><strong>Consumers pull, brokers don&#39;t push:</strong> the consumer specifies an offset, gets back a chunk. Consumers control their own rate — a slow consumer lags instead of OOMing, a batch consumer fetches aggressively. Push wins on latency, loses on diverse consumers and replay. Use long polling to paper over empty pulls.</li><li><strong>ISR is the durability dial:</strong> followers that keep up stay <em>in-sync</em>; a lagging replica drops out of the ISR set and rejoins when it catches up. <code>ack=all</code> waits on the whole ISR set (strongest, slowest); <code>ack=1</code> is leader-only (can lose in-flight messages); <code>ack=0</code> is fire-and-forget (metrics/logging). Name the dial — <code>min.insync.replicas</code> — don&#39;t say &quot;it depends on your consistency needs.&quot;</li><li><strong>Exactly-once is an illusion built from idempotency:</strong> at-least-once delivery + retries means the same message arrives twice — at the producer-broker boundary and again at consumer-offset-commit. Effective-once = idempotent producer (dedupe retries) + commit the consumer offset in the <em>same transaction</em> as the output write. A consumer that processes, writes output, then crashes before committing the offset re-reads and double-counts — that&#39;s the failure to name.</li></ul><div class="tip custom-block"><p class="custom-block-title">💡 Where this design lands vs real Kafka</p><p>The chapter&#39;s generic design is recognizably Kafka: WAL segments, ISR, <code>ack=0/1/all</code>, pull consumers, group coordinator. Where reality moved: Kafka stores consumer offsets <em>in the log itself</em> (<code>__consumer_offsets</code> topic, not an external KV store) and retired ZooKeeper for KRaft — the coordinator became Raft-replicated metadata inside the cluster. Exactly-once = idempotent producer + <code>send_offsets_to_transaction</code>. Details: <a href="/Data-Knowledge/streaming/kafka.html">Kafka internals</a>.</p></div><h3 id="failure-modes-to-volunteer-1" tabindex="-1">Failure modes to volunteer <a class="header-anchor" href="#failure-modes-to-volunteer-1" aria-label="Permalink to &quot;Failure modes to volunteer&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Failure</th><th>Handling</th></tr></thead><tbody><tr><td>Broker dies</td><td>Elected controller rewrites the replica distribution plan; new leader from ISR; new replicas catch up as followers — never co-locate a partition&#39;s replicas on one node</td></tr><tr><td>Slow follower</td><td>Drops out of ISR at the lag bound; commits continue at <code>min.insync.replicas</code>; rejoins on catch-up</td></tr><tr><td>Consumer crash mid-batch</td><td>Offset not committed → successor re-reads from last committed offset; at-least-once, dedupe is the consumer&#39;s job</td></tr><tr><td>Consumer joins/leaves/crashes</td><td>Coordinator triggers rebalance via heartbeat; group leader computes the dispatch plan; consumption pauses group-wide during rebalance</td></tr><tr><td>Retention expires on a decommissioned partition</td><td>Partition drains on the retention clock, not on removal — decreasing partition count is not a shortcut to free disk</td></tr></tbody></table><h3 id="follow-ups-interviewers-ask-1" tabindex="-1">Follow-ups interviewers ask <a class="header-anchor" href="#follow-ups-interviewers-ask-1" aria-label="Permalink to &quot;Follow-ups interviewers ask&quot;">​</a></h3><ul><li><em>&quot;Why not RabbitMQ / why not a database table?&quot;</em> → retention-and-replay vs drain-on-consume; write-heavy sequential access vs B-tree random access. RabbitMQ&#39;s overflow disk is orders of magnitude smaller.</li><li><em>&quot;Push vs pull?&quot;</em> → pull: consumer-controlled rate, batch-friendly, replay-friendly; push only if you must minimize latency for homogeneous fast consumers.</li><li><em>&quot;Walk me through a consumer crash.&quot;</em> → missed heartbeats → coordinator marks dead → rebalance → new consumer resumes from last committed offset in state storage.</li><li><em>&quot;Add a partition — what breaks?&quot;</em> → nothing on write (old messages stay put, no migration); consumers rebalance; keyed ordering for existing keys is preserved only if you don&#39;t remap them.</li><li><em>&quot;Make it exactly-once.&quot;</em> → idempotent producer + transactional offset commit + idempotent sink; name the throughput cost and offer at-least-once + idempotent consumer as the cheaper equivalent.</li></ul><h2 id="design-e-—-ad-click-event-aggregation-pipeline" tabindex="-1">Design E — Ad-click event aggregation pipeline <a class="header-anchor" href="#design-e-—-ad-click-event-aggregation-pipeline" aria-label="Permalink to &quot;Design E — Ad-click event aggregation pipeline&quot;">​</a></h2><p><em>&quot;Aggregate ad clicks: per-ad counts over rolling windows, top-N ads per minute, correct enough to bill on.&quot;</em> (Vol 2 ch.6 — the canonical streaming-aggregation case.)</p><h3 id="requirements-4" tabindex="-1">Requirements <a class="header-anchor" href="#requirements-4" aria-label="Permalink to &quot;Requirements&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Question</th><th>Assumed answer</th></tr></thead><tbody><tr><td>Queries</td><td>Count per ad_id over last M minutes; top-N ads over last M minutes — filterable by country / ip / user_id; refreshed every minute</td></tr><tr><td>Scale</td><td>~1B clicks/day, ~2M ads, +30% YoY</td></tr><tr><td>Latency</td><td>A few minutes end-to-end — billing and reporting, not RTB&#39;s sub-second</td></tr><tr><td>Correctness</td><td>Exactly-once or bust — a few percent of duplicates is a few million dollars of billing error</td></tr><tr><td>Edge cases</td><td>Duplicate sends (client retries), late events (hours), partial system failures</td></tr></tbody></table><h3 id="capacity-math-4" tabindex="-1">Capacity math <a class="header-anchor" href="#capacity-math-4" aria-label="Permalink to &quot;Capacity math&quot;">​</a></h3><ul><li><strong>QPS:</strong> 10⁹ events / ~10⁵ s/day ≈ <strong>10k avg</strong>; ×5 peak factor = <strong>50k peak QPS</strong> — always state both; systems are sized for peak.</li><li><strong>Storage:</strong> ~0.1 KB/event × 10⁹ = <strong>~100 GB/day raw</strong>, ~3 TB/month — trivially cheap; the cost is in <em>state</em>, not bytes.</li><li><strong>The number that matters:</strong> two message-queue hops (raw events in, aggregates out) sized for the growth multiple — pre-allocate partitions for 30%/yr; changing the key→partition mapping mid-flight remaps every ad_id.</li></ul>',13)),(s(),i(d,null,{default:t(()=>[a(o,{id:"mermaid-1273",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20LW%5B%22Log%20watchers%3Cbr%2F%3Etail%20click%20logs%22%5D%20--%3E%20MQ1%5B%22Message%20queue%3Cbr%2F%3Eraw%20click%20events%22%5D%0A%20%20%20%20subgraph%20Agg%5B%22Aggregation%20service%20%E2%80%94%20streaming%22%5D%0A%20%20%20%20%20%20%20%20MAP%5B%22Map%20node%3Cbr%2F%3Eclean%20%2B%20repartition%20by%20ad_id%22%5D%0A%20%20%20%20%20%20%20%20AGG%5B%22Aggregate%20nodes%3Cbr%2F%3E1-min%20tumbling%20windows%3Cbr%2F%3Eheap%20for%20top-N%22%5D%0A%20%20%20%20%20%20%20%20RED%5B%22Reduce%20node%3Cbr%2F%3Emerge%20per-node%20top-N%22%5D%0A%20%20%20%20%20%20%20%20MAP%20--%3E%20AGG%20--%3E%20RED%0A%20%20%20%20end%0A%20%20%20%20MQ1%20--%3E%20MAP%0A%20%20%20%20RED%20--%3E%20MQ2%5B%22Message%20queue%3Cbr%2F%3Eper-minute%20counts%20%2B%20top-N%22%5D%0A%20%20%20%20MQ2%20--%3E%20DW%5B%22Database%20writer%22%5D%20--%3E%20ADB%5B%22Aggregated%20store%3Cbr%2F%3Edashboards%20%2B%20billing%22%5D%0A%20%20%20%20LW%20--%3E%20RDS%5B%22Raw%20event%20store%3Cbr%2F%3Ecold%2C%20replayable%22%5D%0A%20%20%20%20RDS%20--%3E%7Crecalc%20path%7C%20RS%5B%22Recalc%20service%3Cbr%2F%3Ededicated%20cluster%22%5D%20--%3E%20MQ2%0A%20%20%20%20ADB%20--%3E%20Q%5B%22Query%20service%3Cbr%2F%3Edashboards%22%5D%0A%20%20%20%20BJ%5B%22End-of-day%20batch%3Cbr%2F%3Ereconciliation%22%5D%20-.-%3E%7Cdiff%20vs%20real-time%7C%20ADB%0A"})]),fallback:t(()=>[...e[4]||(e[4]=[n(" Loading... ",-1)])]),_:1})),e[11]||(e[11]=r('<h3 id="decision-points-—-narrate-the-trade-off-2" tabindex="-1">Decision points — narrate the trade-off <a class="header-anchor" href="#decision-points-—-narrate-the-trade-off-2" aria-label="Permalink to &quot;Decision points — narrate the trade-off&quot;">​</a></h3><ul><li><strong>Kappa over lambda:</strong> one streaming path; reprocessing is a <em>replay through the same aggregation service</em> on a dedicated cluster, not a second batch codebase to keep in sync. Keep the raw events — when an aggregation bug ships, you recalculate from raw starting at the deploy that broke it.</li><li><strong>Event time + watermark, reconciled later:</strong> event time is correct for billing; processing time is safer but wrong for late events. Take event time, extend windows by a ~15s watermark for stragglers, and accept that long-delayed events get corrected by the end-of-day batch — don&#39;t design for the 0.1% case in the hot path.</li><li><strong>Tumbling for counts, sliding for top-N:</strong> per-minute counts are non-overlapping tumbling windows; &quot;top-N in last M minutes&quot; is a sliding window over M evaluated each minute — state both window types by name.</li><li><strong>Dedupe via offset atomicity, not magic:</strong> an aggregator that publishes results then crashes <em>before</em> committing the upstream offset reprocesses the range on restart → double counts. Commit the offset <em>after</em> the downstream ack — and for true exactly-once, wrap publish + offset-commit in one transaction (Kafka transactions), or make the sink idempotent so the duplicate write is harmless.</li><li><strong>Hot ad skew:</strong> partitioning by ad_id sends a mega-advertiser&#39;s 300-event burst at one node&#39;s 100-event capacity. Mitigate with local pre-aggregation + a global reduce, and a resource manager that splits hot keys across extra aggregate nodes — named as the same global-local aggregation pattern every real system uses.</li></ul><h3 id="failure-modes-to-volunteer-2" tabindex="-1">Failure modes to volunteer <a class="header-anchor" href="#failure-modes-to-volunteer-2" aria-label="Permalink to &quot;Failure modes to volunteer&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Failure</th><th>Handling</th></tr></thead><tbody><tr><td>Aggregation node dies</td><td>In-memory window state lost → recover from latest snapshot (offsets + running counts) then replay from upstream since snapshot</td></tr><tr><td>Downstream write acked, offset commit fails</td><td>Replay → duplicates → mitigated only by idempotent sink or transactional commit</td></tr><tr><td>Events arrive hours late</td><td>Outside watermark → missed in real-time counts; corrected by end-of-day reconciliation batch</td></tr><tr><td>One ad gets 100× clicks</td><td>Hot-key split: partial aggregates per node, single reduce merges</td></tr><tr><td>Consumer group rebalance storm at scale</td><td>Hundreds of consumers = minutes of paused consumption; scale during off-peak, pre-allocate partitions</td></tr></tbody></table><h3 id="follow-ups-interviewers-ask-2" tabindex="-1">Follow-ups interviewers ask <a class="header-anchor" href="#follow-ups-interviewers-ask-2" aria-label="Permalink to &quot;Follow-ups interviewers ask&quot;">​</a></h3><ul><li><em>&quot;How late is too late — what happens to a 6-hour-late event?&quot;</em> → watermark covers seconds-to-minutes; the reconciliation batch (sorted replay of raw events) fixes the rest; name the residual: real-time counts are provisional, reconciled counts are the billable truth.</li><li><em>&quot;Exactly-once — how, precisely?&quot;</em> → the atomic unit is <em>output write + upstream offset commit</em>. Kafka transactions make it native; otherwise idempotent sink keyed on (ad_id, window) with commit-after-ack. If they push further: that&#39;s a distributed transaction, and it costs throughput.</li><li><em>&quot;Raw or aggregated storage — pick one.&quot;</em> → both, deliberately: raw in cheap columnar storage (replay + recalculation insurance), aggregates in a write+read-optimized time-series store for dashboards. Raw is backup you hope never to query; aggregated is what billing reads.</li><li><em>&quot;What do you monitor?&quot;</em> → per-stage latency stamps, Kafka records-lag (not queue size — it&#39;s a log, not a queue), aggregation node resources, and a completeness check on the reconciliation diff.</li></ul><div class="tip custom-block"><p class="custom-block-title">💡 Vol 2 depth patterns — the estimation upgrade</p><p>Vol 2&#39;s back-of-envelope is strictly better than Vol 1&#39;s &quot;compute the average.&quot; Each chapter layers refinements on the same skeleton — learn the moves, not the numbers:</p><ul><li><strong>Average → peak, always:</strong> click QPS = 1B/day ≈ 10k avg, then explicitly ×5 for peak. Sizing to average is the junior tell.</li><li><strong>Traffic → traffic × retention:</strong> raw events are cheap; multiply by retention days and replication factor before you flinch — then tier it (7 days raw → 30 days at 1-min → 1 year at 1-hour resolution in the metrics chapter).</li><li><strong>Growth is a design input, not a footnote:</strong> +30%/yr → 2× in ~3 years → pre-allocate Kafka partitions and storage headroom now, because re-keying partitions later is a migration.</li><li><strong>Funnels estimate reads from writes:</strong> the hotel chapter derives page-view QPS from reservation TPS through a 10%-per-step conversion funnel — invent a funnel whenever the &quot;query rate&quot; isn&#39;t given.</li><li><strong>State beats bytes:</strong> the binding constraint is never MB/s — it&#39;s dedupe windows, partition counts, in-memory aggregation state. Say which one binds.</li></ul></div><h2 id="worked-mini-case-—-xu-s-4-steps-end-to-end" tabindex="-1">Worked mini-case — Xu&#39;s 4 steps end-to-end <a class="header-anchor" href="#worked-mini-case-—-xu-s-4-steps-end-to-end" aria-label="Permalink to &quot;Worked mini-case — Xu&#39;s 4 steps end-to-end&quot;">​</a></h2><p><em>&quot;Design a news-feed-style analytics dashboard: product managers see a ranked feed of their metrics, updating near-real-time.&quot;</em> Watch how each step produces something the interviewer can score.</p><h3 id="step-1-—-scope-minutes-0-7" tabindex="-1">Step 1 — Scope (minutes 0-7) <a class="header-anchor" href="#step-1-—-scope-minutes-0-7" aria-label="Permalink to &quot;Step 1 — Scope (minutes 0-7)&quot;">​</a></h3><p>Questions, in the order a senior asks them:</p><ul><li><em>&quot;Feed of what — precomputed metric tiles, or queries run on click?&quot;</em> → determines whether this is a serving problem or a compute problem.</li><li><em>&quot;How fresh — seconds, minutes, hourly?&quot;</em> → PM dashboards: interviewer says &quot;under a minute&quot; — that&#39;s a streaming SLO, not micro-batch hourly.</li><li><em>&quot;How many dashboards, how many metrics each, how many concurrent viewers?&quot;</em> → 10k PMs, ~20 tiles each, ~500 concurrent.</li><li><em>&quot;Ranked how — chronological, or by anomaly/interest score?&quot;</em> → interviewer says ranked by &quot;what changed most&quot; — the feed is a ranking problem <em>and</em> a serving problem.</li><li><em>&quot;Correctness — can a number restate?&quot;</em> → yes, within a stated window; label late-arriving corrections.</li></ul><h3 id="step-2-—-buy-in-minutes-7-15" tabindex="-1">Step 2 — Buy-in (minutes 7-15) <a class="header-anchor" href="#step-2-—-buy-in-minutes-7-15" aria-label="Permalink to &quot;Step 2 — Buy-in (minutes 7-15)&quot;">​</a></h3><p>Sketch two flows — exactly like Xu&#39;s feed split into publishing vs building — then check them against a back-of-envelope before committing:</p>',14)),(s(),i(d,null,{default:t(()=>[a(o,{id:"mermaid-1463",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20Ingest%5B%22Metric%20publishing%22%5D%0A%20%20%20%20%20%20%20%20E%5B%22Event%20streams%22%5D%20--%3E%20S%5B%22Stream%20processor%22%5D%0A%20%20%20%20%20%20%20%20S%20--%3E%20A%5B%22Aggregate%20store%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Serve%5B%22Feed%20building%22%5D%0A%20%20%20%20%20%20%20%20A%20--%3E%20R%5B%22Ranker%22%5D%0A%20%20%20%20%20%20%20%20R%20--%3E%20C%5B%22Feed%20cache%22%5D%0A%20%20%20%20%20%20%20%20C%20--%3E%20D%5B%22Dashboard%22%5D%0A%20%20%20%20end%0A"})]),fallback:t(()=>[...e[5]||(e[5]=[n(" Loading... ",-1)])]),_:1})),e[12]||(e[12]=r('<p>The math that buys in the design: 500 concurrent dashboards × 20 tiles = 10k tile reads per refresh. If tiles are query-on-read against raw data, every refresh is 10k OLAP scans — absurd. Precompute tiles into an aggregate store, rank into a feed cache, serve reads from cache. The estimation <em>is</em> the argument for precomputation — say that out loud.</p><h3 id="step-3-—-deep-dive-minutes-15-35" tabindex="-1">Step 3 — Deep dive (minutes 15-35) <a class="header-anchor" href="#step-3-—-deep-dive-minutes-15-35" aria-label="Permalink to &quot;Step 3 — Deep dive (minutes 15-35)&quot;">​</a></h3><p>Pick the two components with real depth, not the plumbing:</p><ul><li><strong>Aggregate store vs query-on-read</strong> — the classic fan-out trade-off. Precompute (push model): reads are cheap, writes do the work, restatement must propagate through every aggregate that consumed an event. Query-on-read (pull model): always correct, read cost explodes. Offer the hybrid — precomputed tiles for the feed, on-demand drill-down for ad-hoc — and name why.</li><li><strong>Ranking under restatement</strong> — &quot;what changed most&quot; recomputes whenever late data lands. Rank on a snapshot of aggregates, version the snapshot, and let the feed label tiles &quot;updated 2m ago&quot; rather than promising instant consistency between rank and value.</li></ul><h3 id="step-4-—-wrap-up-minutes-35-45" tabindex="-1">Step 4 — Wrap up (minutes 35-45) <a class="header-anchor" href="#step-4-—-wrap-up-minutes-35-45" aria-label="Permalink to &quot;Step 4 — Wrap up (minutes 35-45)&quot;">​</a></h3><p>Run the checklist below: name the first bottleneck (aggregate write amplification under restatement), the 10× plan (shard aggregates by metric, batch ranker recomputes), and recap the two trade-offs you actually made — precompute over freshness, ranked-snapshot over live consistency.</p><h2 id="the-wrap-up-checklist" tabindex="-1">The wrap-up checklist <a class="header-anchor" href="#the-wrap-up-checklist" aria-label="Permalink to &quot;The wrap-up checklist&quot;">​</a></h2><p>Xu&#39;s step 4 is the easiest place to pick up free points — and the most skipped. In the last 5 minutes, hit every row:</p><table tabindex="0"><thead><tr><th>Beat</th><th>Say something like</th><th>Signal</th></tr></thead><tbody><tr><td>Bottleneck</td><td>&quot;The first thing that breaks is ___ at ~10× load&quot;</td><td>You&#39;ve operated systems, not just drawn them</td></tr><tr><td>Mitigation</td><td>&quot;I&#39;d mitigate by ___&quot; — one per bottleneck</td><td>You debug toward a fix, not a shrug</td></tr><tr><td>Failure case</td><td>&quot;If the stream processor dies, replays catch up from offsets; dashboards go stale, not wrong&quot;</td><td>Graceful degradation beats silent corruption</td></tr><tr><td>Ops story</td><td>&quot;I&#39;d watch end-to-end freshness lag and aggregate restatement rate&quot;</td><td>Operability is part of the design</td></tr><tr><td>Next scale curve</td><td>&quot;At 10× viewers the feed cache fans out; at 10× metrics the aggregate store shards&quot;</td><td>You think in orders of magnitude</td></tr><tr><td>Trade-off recap</td><td>&quot;I chose precompute over query-on-read because the refresh math demanded it — the cost is restatement complexity&quot;</td><td>Closing the loop on your own decisions</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight</p><p>Never say the design is finished or perfect. Xu&#39;s rule: there is always something to improve, and claiming otherwise reads as someone who has never been paged by their own architecture. One honest limitation beats ten defensive justifications.</p></div><h2 id="the-junior-vs-senior-rubric" tabindex="-1">The junior vs senior rubric <a class="header-anchor" href="#the-junior-vs-senior-rubric" aria-label="Permalink to &quot;The junior vs senior rubric&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dimension</th><th>Junior answer</th><th>Senior answer</th></tr></thead><tbody><tr><td>Requirements</td><td>Starts drawing immediately</td><td>Spends the first 8 min extracting constraints; states assumptions explicitly</td></tr><tr><td>Scale</td><td>&quot;It should scale&quot;</td><td>Numbers: &quot;10k/s × 600B ≈ 6MB/s — the log is trivial; dedupe window is the real cost&quot;</td></tr><tr><td>Components</td><td>Names tools (&quot;Kafka, Flink, Spark&quot;)</td><td>Names <em>patterns</em>, tools in parentheses — and says why each exists</td></tr><tr><td>Failure modes</td><td>Answers when asked</td><td>Volunteers the top 3 + mitigations unprompted</td></tr><tr><td>Trade-offs</td><td>One design, no alternatives</td><td>&quot;Option A is simpler, option B survives restatement — I&#39;d pick A because the SLA tolerates it&quot;</td></tr><tr><td>Consistency</td><td>&quot;Exactly-once&quot; as a word</td><td>Effective-once: names the guarantee boundary and where it ends</td></tr><tr><td>Recovery</td><td>Doesn&#39;t mention it</td><td>Names replay path, backfill story, and which layer is canonical</td></tr><tr><td>Scope</td><td>Designs the whole internet</td><td>Designs what&#39;s asked, notes what&#39;s deliberately out of scope</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">⚠️ The trap that reads as junior</p><p>Drawing a beautiful architecture with no numbers and no stated assumptions. Interviewers consistently write &quot;great diagram, never told me why&quot; in feedback. A messy sketch with capacity math and named failure modes beats a clean one without — every time.</p></div><h2 id="🧠-quiz" tabindex="-1">🧠 Quiz <a class="header-anchor" href="#🧠-quiz" aria-label="Permalink to &quot;🧠 Quiz&quot;">​</a></h2>',14)),a(l,{questions:[{q:"What should occupy the first ~8 minutes of a 45-minute design round?",options:["Listing the tools you would use","Estimating storage costs","Extracting requirements — freshness, correctness tolerance, consumers, replay needs — and stating assumptions","Drawing the high-level boxes"],correct:2,explain:"Requirements determine the design. Candidates who draw first routinely build the wrong system — the requirement questions are themselves the graded signal."},{q:"In a zero-downtime CDC migration, what does the snapshot need to guarantee?",options:["It must run during off-peak hours only","It must include indexes for fast queries","It must finish faster than 4 hours","It must be anchored to a WAL/LSN position so CDC applies changes from exactly that point with no gap or overlap"],correct:3,explain:"A snapshot at an arbitrary point plus a log tail started separately leaves a gap or overlap of changes. LSN-anchored consistency is the correctness mechanism of the whole design."},{q:"An interviewer asks to make your pipeline exactly-once end-to-end. The senior response is?",options:["Explain that true end-to-end exactly-once is impossible, offer effective-once via idempotent sinks and dedupe, and name the guarantee boundary","Increase checkpoint frequency","Add a distributed transaction across all sinks","Enable Kafka exactly-once semantics everywhere"],correct:0,explain:"Exactly-once ends at the last framework-managed write. External sinks make it at-least-once plus idempotency — effective-once. Knowing where the guarantee stops is the answer being tested."},{q:"In a metrics/feature platform, what is the central design tension?",options:["How many Spark executors the backfill needs","One metric definition feeding BI and ML paths will drift unless definitions live in one versioned spec compiled to both","Whether to use Redis or DynamoDB for online serving","Whether dashboards should refresh every 5 or 15 minutes"],correct:1,explain:"Two engines computing the same metric is a guaranteed drift source. The platform answer is definitions-as-code with version pinning — and the follow-up vocabulary is training-serving skew and point-in-time joins."},{q:"What most distinguishes a senior design answer?",options:["Naming more technologies","Drawing more detailed diagrams","Answering every follow-up instantly","Volunteering the top failure modes and their mitigations before being asked"],correct:3,explain:"Proactively naming failure modes demonstrates production ownership — the thing the round simulates. Reactive answers, even correct ones, score lower."},{q:"Why should the lake, not the OLAP store, be the canonical layer in a dual-sink design?",options:["Lake storage is cheaper per query","The lake is faster to query","The OLAP store is a disposable projection — if sinks disagree you rebuild the projection from the canonical lake","OLAP stores cannot deduplicate"],correct:2,explain:"Naming which layer is source of truth defines your recovery story. A disposable projection can always be rebuilt; making the fast layer canonical couples recovery to the component most likely to need rebuilds."}]}),a(l,{questions:[{q:"In Xu's 4-step framework, what is the purpose of the buy-in step?",options:["To finish the estimation before drawing anything","To write the final database schema","To sketch a high-level blueprint, get interviewer agreement, and sanity-check it with back-of-envelope numbers","To list every technology you will use"],correct:2,explain:"Step 2 produces a 5-to-8-box blueprint the interviewer has agreed to, then estimation proves it fits the scale. Skipping buy-in means deep-diving a design nobody signed off on."},{q:"Using the estimation cheat-sheet: 20k events/s at 1 KB each produces roughly how much storage per day?",options:["~2 TB/day","~20 TB/day","~20 GB/day","~200 GB/day"],correct:0,explain:"20k ev/s x 1 KB x ~10^5 s/day = ~2x10^9 KB = ~2 TB/day. The shortcut is events-per-second times size times ten-to-the-fifth seconds — three multiplications, no calculator."},{q:"What does peak QPS estimation typically assume in Xu's method?",options:["Peak is only relevant for writes, not reads","Peak equals average divided by 2","Peak equals average multiplied by total users","Peak is roughly 2x average QPS"],correct:3,explain:"Xu uses peak ~= 2x average as the sizing rule of thumb — for Twitter he estimated 3.5k average and ~7k peak. For data platforms the analogue is the end-of-window batch burst, which sizes buffers, not daily averages."},{q:"In the wrap-up step, which closing move scores worst?",options:["Naming the first bottleneck and its mitigation","Recapping the trade-offs you made","Describing what you would monitor in production","Stating the design is complete and has no weaknesses"],correct:3,explain:"Xu is explicit: never claim the design is perfect. Every architecture has a first thing that breaks — saying so demonstrates you have operated real systems; claiming completeness reads as inexperience."}]}),a(l,{questions:[{q:"In the distributed message queue case, what mechanism stops one slow replica from stalling a whole partition?",options:["In-sync replicas: a follower that lags beyond the bound drops out of the ISR set and rejoins on catch-up, so commits proceed at min-insync-replicas","The leader waits for every configured replica before committing","The coordinator rewrites the message to all replicas synchronously","Consumers read directly from whichever replica is closest"],correct:0,explain:"ISR is the durability-versus-latency dial: ack=all waits on the full ISR set for strongest durability, but a straggler falls out of the set rather than blocking commits. ack=1 or ack=0 trade durability for latency explicitly."},{q:"In the ad-click pipeline, an aggregator publishes results then crashes before committing its upstream offset. What happens, and what is the fix?",options:["The watermark drops the replayed events","Nothing — Kafka dedupes by message key automatically","The reduce node filters the duplicates","The range is reprocessed and clicks double-count; fix by committing the offset only after the downstream ack, and for true exactly-once wrap output-write plus offset-commit in one transaction or make the sink idempotent"],correct:3,explain:"Offset-before-output loses data; offset-after-output duplicates data. Exactly-once is really atomicity between the output write and the offset commit — transactions, or an idempotent sink that makes the duplicate harmless."},{q:"The ad-click case uses event time plus a ~15s watermark. What does the watermark NOT solve?",options:["Client clock skew on event timestamps","Events arriving hours late — those are corrected by the end-of-day batch reconciliation, not in the streaming path","Window boundaries computed on processing time","Events arriving a few seconds late"],correct:1,explain:"Watermarks absorb bounded lateness at the cost of added latency. Long-delayed events are a low-probability tail: reconcile them with a batch job over raw data instead of complicating the hot path."}]}),e[13]||(e[13]=r('<h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="https://bytebytego.com/courses/system-design-interview/a-framework-for-system-design-interviews" target="_blank" rel="noreferrer">A Framework for System Design Interviews — ByteByteGo</a> — the 4-step structure this chapter&#39;s 5-phase framework adapts for data platforms.</li><li><a href="https://bytebytego.com/" target="_blank" rel="noreferrer">System Design Interview Vol 1 &amp; 2 — Alex Xu</a> — the standard design-round vocabulary; chapters on rate limiters and metrics pipelines map directly to DE rounds.</li><li><strong>System Design Interview: An Insider&#39;s Guide</strong> — Alex Xu (2020), <a href="https://bytebytego.com/" target="_blank" rel="noreferrer">ByteByteGo</a> — source of the 4-step framework, the estimation cheat-sheet, and the wrap-up discipline this chapter maps to data platforms.</li><li><strong>System Design Interview: An Insider&#39;s Guide, Volume 2</strong> — Alex Xu &amp; Sahn Lam (2022), <a href="https://bytebytego.com/" target="_blank" rel="noreferrer">ByteByteGo</a> — source of the distributed message queue and ad-click aggregation worked cases plus the peak-factor, growth, retention-tiering, and funnel estimation refinements.</li><li><a href="https://dataintensive.net/" target="_blank" rel="noreferrer">Designing Data-Intensive Applications — Kleppmann</a> — the conceptual basis for every consistency/partitioning/streaming trade-off in this chapter.</li><li><a href="https://www.startdataengineering.com/post/de_interview_sd" target="_blank" rel="noreferrer">Start Data Engineering — DE system design interview series</a> — DE-specific design round walkthroughs with real problem statements.</li><li><a href="https://debezium.io/documentation/reference/stable/connectors/postgresql.html#postgresql-snapshots" target="_blank" rel="noreferrer">Debezium documentation — snapshots</a> — snapshot modes and LSN consistency for the migration design.</li><li><a href="https://docs.confluent.io/kafka/design/delivery-semantics.html" target="_blank" rel="noreferrer">Confluent — delivery semantics</a> — at-most/at-least/exactly-once definitions for the guarantee-boundary answer.</li><li><a href="https://docs.feast.dev/" target="_blank" rel="noreferrer">feast.dev — feature store concepts</a> — offline/online stores and point-in-time joins as implemented by a real feature platform.</li></ul>',2))])}const q=c(m,[["render",p]]);export{v as __pageData,q as default};
